SELECT lianxu_days FROM (SELECT * FROM ( SELECT user_code, MAX(days) lianxu_days, MIN(login_day) start_date, MAX(login_day) end_date FROM (SELECT user_code, @cont_day := (CASE WHEN (@last_uid = user_code AND DATEDIFF(sleep_diarytime, @last_dt) = 1) THEN (@cont_day + 1) WHEN (@last_uid = user_code AND DATEDIFF(sleep_diarytime, @last_dt) < 1) THEN (@cont_day + 0) ELSE 1 END) AS days, (@cont_ix := (@cont_ix + IF(@cont_day = 1, 1, 0))) AS cont_ix, @last_uid := user_code, @last_dt := sleep_diarytime login_day FROM (SELECT user_code, DATE(sleep_diarytime) sleep_diarytime FROM yh_sleep_user_diary WHERE user_code = #{usercode}
ORDER BY user_code, sleep_diarytime) AS t, (SELECT @last_uid := '', @last_dt := '', @cont_ix := 0, @cont_day := 0) AS t1 ) AS t2 GROUP BY user_code, cont_ix
) tmp ORDER BY lianxu_days DESC) ntmp GROUP BY user_code;

SELECT lianxu_days FROM (SELECT * FROM ( SELECT user_code, MAX(days) lianxu_days, MIN(login_day) start_date, MAX(login_day) end_date FROM (SELECT user_code, @cont_day := (CASE WHEN (@last_uid = user_code AND DATEDIFF(sleep_diarytime, @last_dt) = 1) THEN (@cont_day + 1) WHEN (@last_uid = user_code AND DATEDIFF(sleep_diarytime, @last_dt) < 1) THEN (@cont_day + 0) ELSE 1 END) AS days, (@cont_ix := (@cont_ix + IF(@cont_day = 1, 1, 0))) AS cont_ix, @last_uid := user_code, @last_dt := sleep_diarytime login_day FROM (SELECT user_code, DATE(sleep_diarytime) sleep_diarytime FROM yh_sleep_user_diary WHERE DATE_FORMAT( sleep_diarytime, '%Y%m' ) = DATE_FORMAT( CURDATE( ) , '%Y%m' ) and user_code = #{usercode}
ORDER BY user_code, sleep_diarytime) AS t, (SELECT @last_uid := '', @last_dt := '', @cont_ix := 0, @cont_day := 0) AS t1 ) AS t2 GROUP BY user_code, cont_ix
) tmp ORDER BY lianxu_days DESC) ntmp GROUP BY user_code;
